const $=id=>document.getElementById(id),C=MealCore;let allRows=[],allScope='',mode='real',metric='total',selected=null,map=null,layer=null,view=null,lastMapMode=null,drawFrame=null;
const pointLayers=new Map();
const inferredAddress=r=>r.address_match==='name_city'||r.location?.match_method==='name_city';
const cityShortcuts=[['화성','hwaseong'],['용인','yongin'],['수원','suwon'],['평택','pyeongtaek']];
function mapView(r){if(view?.rows===r)return view;const points=C.group(r.filter(x=>x.location),x=>x.location.lat+'|'+x.location.lng);points.forEach(g=>{g.lat=g.rows[0].location.lat;g.lng=g.rows[0].location.lng;g.inferred=g.rows.some(inferredAddress);const names=[...new Set(g.rows.map(r=>r.merchant))];g.label=names.length>1?names.length+'개 사용처 · 같은 주소':names[0];});view={rows:r,points,regions:C.group(r,x=>x.spending_region)};pointLayers.clear();if(layer)layer.clearLayers();lastMapMode=null;return view;}
let filteredKey=null,filteredRows=null;
let restaurantIndex=null;const typeCache=new Map(),rowTypeCache=new WeakMap();
function restaurantType(row){if(rowTypeCache.has(row))return rowTypeCache.get(row);const key=row.location?MealRestaurants.venueKey(row):'name|'+row.merchant;if(!typeCache.has(key)){const profile=MealRestaurants.profileFor(row,restaurantProfiles||{},restaurantIndex);typeCache.set(key,MealRestaurants.classify(row,profile));}const result=typeCache.get(key);rowTypeCache.set(row,result);return result;}
function typeBadges(row){const type=restaurantType(row);return type.tags.map(tag=>`<span class="badge restaurant-type" title="${safe(type.evidence)}">${safe(tag)}</span>`).join('')+(type.provisional?'<span class="type-provisional">상호 추정 포함</span>':'');}
const money=v=>v==null?'계산 불가':Math.round(v).toLocaleString('ko-KR')+'원';
const compact=v=>v==null?'미공개':v>=100000000?(v/100000000).toFixed(1)+'억':v>=10000?(v/10000).toLocaleString('ko-KR',{maximumFractionDigits:1})+'만':Math.round(v).toLocaleString('ko-KR');
const safe=s=>String(s??'미공개').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function rows(){const f={search:$('search').value.trim(),period:$('period').value,institution:$('institution').value,region:$('region').value,city:$('city').value,category:$('category').value,restaurantType:$('restaurant-type').value||'all'};const key=mode+'|'+JSON.stringify(f);if(filteredKey!==key){filteredKey=key;filteredRows=C.filter(mode==='demo'?C.demoRows():allRows,f);if(f.restaurantType!=='all')filteredRows=filteredRows.filter(r=>restaurantType(r).tags.includes(f.restaurantType));}return filteredRows;}
function options(id,values){const old=$(id).value;$(id).replaceChildren(new Option(id==='period'?'전체 기간':id==='institution'?'전체 기관':id==='city'?'전체 시/군':'전체 지역','all'),...values.map(v=>new Option(id==='city'?v+'시':v,v)));if(values.includes(old))$(id).value=old;}
function updateCityShortcuts(){const counts=new Map();allRows.forEach(r=>counts.set(r.institution,(counts.get(r.institution)||0)+1));cityShortcuts.forEach(([city,id])=>{const button=$('quick-'+id);const count=counts.get(city+'시')||0;button.disabled=!allRows.length;button.textContent=city+'시 · '+count.toLocaleString('ko-KR')+'건';button.onclick=()=>chooseInstitution(city+'시');});const council=$('quick-hwaseong-council');council.disabled=!allRows.length;council.textContent='화성시의회 · '+(counts.get('화성시의회')||0).toLocaleString('ko-KR')+'건';council.onclick=()=>chooseInstitution('화성시의회');}
function chooseInstitution(name){if(!allRows.some(r=>r.institution===name))return;$('search').value='';['period','region','city','category','institution','restaurant-type'].forEach(id=>$(id).value='all');if(mode!=='real')setMode('real');$('institution').value=name;selected=null;$('detail').hidden=true;render();const city=name==='화성시의회'?'화성':cityShortcuts.find(([city])=>city+'시'===name)?.[0];if(map&&city)focusRegion(rows(),C.cities[city]);}
function setMode(next){mode=next;selected=null;$('detail').hidden=true;$('real').classList.toggle('active',next==='real');$('demo').classList.toggle('active',next==='demo');const r=next==='demo'?C.demoRows():allRows;options('period',[...new Set(r.map(r=>(r.date||'').slice(0,7)).filter(Boolean))].sort().reverse());options('institution',[...new Set(r.map(r=>r.institution))].sort());options('region',Object.keys(C.regions));options('city',Object.keys(C.cities));updateCityShortcuts();$('mode-note').textContent=next==='demo'?'화면 체험 중 · 기관·식당·금액·위치 모두 가상 자료입니다.':'수집 범위: '+allScope+' 미수집은 지출 0원이 아닙니다.';$('legend-label').textContent=next==='demo'?'가상 지출 · 실제 자료 아님':'공개자료 지출 · 주황: 상호·지역 대조';render();}
function render(){const r=rows(),v=mapView(r),s=C.stats(r);const institution=$('institution').value;$('selection-note').hidden=institution==='all';$('selection-note').textContent=institution+' 집행 '+s.count.toLocaleString('ko-KR')+'건 · 지도 표시 '+r.filter(x=>x.location).length.toLocaleString('ko-KR')+'건. 주소 미확인 내역은 아래 목록에서 볼 수 있습니다.';$('total').innerHTML=Number(s.total).toLocaleString('ko-KR')+'<em>원</em>';$('count').textContent=s.count.toLocaleString()+'건';$('per-person').textContent=money(s.perPerson);$('coverage').textContent=`지도 사용처 ${v.points.length.toLocaleString()}곳 · 인당 계산 ${s.knownCount}건 · 기재 연인원 ${s.people}명 · 지역 확인 ${r.filter(x=>x.spending_region).length}건 · 좌표 확인 ${r.filter(x=>x.location).length}건 / ${r.length}건`;$('results-title').textContent=`${$('institution').value!=='all'?$('institution').value+' ':''}집행 내역 ${s.count}건${s.count>200?' · 금액 상위 200건 표시':''}`;$('results').replaceChildren();r.slice().sort((a,b)=>b.amount_krw-a.amount_krw).slice(0,200).forEach(x=>{const el=document.createElement('button');el.className='result';el.innerHTML=`<div class="result-top"><h3>${safe(x.merchant)}</h3><span class="amount">${money(x.amount_krw)}</span></div><div class="metadata">${safe(x.institution)} · ${safe(x.department)}<br>${safe(x.date)} · 기재 ${x.participants??'미공개'}명</div>${typeBadges(x)}<span class="badge">${safe(x.category)}</span>${inferredAddress(x)?'<span class="badge pending">상호·지역 대조 주소</span>':''}${!x.location?'<span class="badge pending">위치 확인 대기</span>':''}<span class="per-person">1인당 ${money(x.participants>0?x.amount_krw/x.participants:null)}</span>`;el.onclick=()=>show([x]);$('results').append(el);});if(!r.length)$('results').innerHTML='<div class="empty">조건에 맞는 공개자료가 없습니다.<br>기간이나 기관 필터를 바꿔 보세요.</div>';scheduleDraw();}
function focusRegion(items,fallback){const points=items.filter(r=>r.location).map(r=>[r.location.lat,r.location.lng]);if(points.length)map.fitBounds(L.latLngBounds(points).pad(.25),{maxZoom:12,padding:[55,90]});else map.setView(fallback,10);}
function scheduleDraw(){if(drawFrame!=null)return;drawFrame=requestAnimationFrame(()=>{drawFrame=null;draw();});}
function draw(){
  if(!map||!view)return;
  const close=map.getZoom()>=9,modeKey=close?'points':'regions';
  if(lastMapMode!==modeKey){layer.clearLayers();pointLayers.clear();lastMapMode=modeKey;}
  $('zoom-label').textContent=close?'식당별 지출 · 실제 좌표':'지역별 지출';
  if(close){
    const viewport=map.getBounds(),bounds=viewport.pad(.15);
    const visible=C.visiblePoints(view.points,{south:bounds.getSouth(),north:bounds.getNorth(),west:bounds.getWest(),east:bounds.getEast()});
    const wanted=new Set(visible.map(g=>g.key));
    for(const [key,entry] of pointLayers){if(!wanted.has(key)){layer.removeLayer(entry.marker);pointLayers.delete(key);}}
    const onScreen=C.visiblePoints(visible,{south:viewport.getSouth(),north:viewport.getNorth(),west:viewport.getWest(),east:viewport.getEast()});
    const ranked=onScreen.slice().sort((a,b)=>(metric==='total'?b.total-a.total:(b.perPerson??-1)-(a.perPerson??-1))||a.key.localeCompare(b.key));
    const labeled=new Set(ranked.slice(0,30).map(g=>g.key));
    const detailed=map.getZoom()>=14,radius=detailed?7:5;
    for(const g of visible){
      const permanent=labeled.has(g.key);
      let entry=pointLayers.get(g.key);
      if(!entry){
        const marker=L.circleMarker([g.lat,g.lng],{radius,bubblingMouseEvents:false,color:'#ffffff',weight:1,fillColor:g.inferred?'#b77924':'#205b46',fillOpacity:.85}).addTo(layer).on('click',()=>show(g.rows)).on('dblclick',event=>L.DomEvent.stop(event));
        entry={marker,radius,metric:null,permanent:null,detailed:null};pointLayers.set(g.key,entry);
      }
      if(entry.radius!==radius){entry.marker.setRadius(radius);entry.radius=radius;}
      if(entry.metric!==metric||entry.permanent!==permanent||entry.detailed!==detailed){
        entry.marker.unbindTooltip();
        entry.marker.bindTooltip(()=>{const price=money(metric==='total'?g.total:g.perPerson);return permanent?`<button type="button" class="price-marker-button" aria-label="${safe(g.label)} · ${price} · 상세 보기">${detailed?`<span class="venue-label-name">${safe(g.label)}</span>`:''}<b>${price}</b></button>`:safe(g.label)+(g.inferred?' · 상호 대조':'')+' · '+price;},{direction:'top',permanent,interactive:true,bubblingMouseEvents:false,className:g.inferred?'price-label inferred':'price-label'});
        entry.marker.getTooltip().on('click',()=>show(g.rows)).on('dblclick',event=>L.DomEvent.stop(event));
        entry.marker.getTooltip().on('add',()=>{const button=entry.marker.getTooltip().getElement()?.querySelector('button');if(button)button.onclick=event=>{event.stopPropagation();show(g.rows);};});
        entry.metric=metric;entry.permanent=permanent;entry.detailed=detailed;
      }
    }
    $('map-help').textContent=view.points.length?`화면 내 ${onScreen.length.toLocaleString()}곳 · 금액 표시 ${labeled.size}곳${onScreen.length>30?' (금액 큰 순)':''} · 식당명·금액이나 점을 누르면 상세를 볼 수 있어요.`:'이 범위의 식당 좌표는 확인 대기 중입니다. 왼쪽 목록에서 원문 지출을 볼 수 있어요.';
    return;
  }
  layer.clearLayers();pointLayers.clear();
  const regionGroups=new Map(view.regions.map(g=>[g.key,g]));
  for(const [name,coord] of Object.entries(C.regions)){
    const g=regionGroups.get(name),value=g?(metric==='total'?g.total:g.perPerson):null;
    const icon=L.divIcon({className:'money-marker',iconSize:[0,0],html:`<button class="pin ${g?'':'uncollected'}"><span>${safe(name)}</span><b>${g?compact(value)+(value==null?'':'원'):'미수집/조건 없음'}</b></button>`});
    L.marker(coord,{icon,keyboard:true}).addTo(layer).on('click',()=>{$('region').value=name;$('city').value='all';render();focusRegion(rows(),coord);if(g&&!g.rows.some(r=>r.location))show(g.rows);});
  }
  $('map-help').textContent='지역을 누르거나 지도를 확대하면 식당별로 볼 수 있어요.';
}

let restaurantProfiles=null,profilePromise=null,profileFailed=false,selectedDetail=null;
function loadRestaurantProfiles(){
  if(!profilePromise)profilePromise=fetch('restaurant-profiles.json',{cache:'no-cache'}).then(r=>{if(!r.ok)throw Error('식당 정보 로딩 실패');return r.json();}).then(data=>{if(data.format!=='restaurant-profiles-v1'||!data.places)throw Error('식당 정보 형식 오류');restaurantProfiles=data.places;restaurantIndex=MealRestaurants.profileIndex(restaurantProfiles);}).catch(()=>{profileFailed=true;});
  return profilePromise;
}
function externalLink(url,label){return /^https:\/\//.test(url||'')?`<a href="${safe(url)}" target="_blank" rel="noopener noreferrer">${safe(label)} ↗</a>`:'';}
function restaurantInfo(x){
  const R=MealRestaurants,profile=R.profileFor(x,restaurantProfiles||{},restaurantIndex);
  const q=[x.spending_city?x.spending_city+'시':'',x.address||'',x.merchant].filter(Boolean).join(' ');
  const searchUrl='https://map.kakao.com/?q='+encodeURIComponent(q);
  if(mode==='demo')return '<section class="restaurant-info"><h3>식당 소개 · 대표메뉴</h3><p>화면 체험용 가상 식당입니다.</p></section>';
  if(!profile)return `<section class="restaurant-info"><h3>식당 소개 · 대표메뉴</h3><p>${!restaurantProfiles&&!profileFailed?'식당 정보를 불러오는 중입니다…':profileFailed?'식당 정보를 불러오지 못했습니다. 지도에서 확인해 주세요.':'이 사용처의 업종·메뉴·가격은 아직 확인되지 않았습니다.'}</p>${externalLink(searchUrl,'식당·메뉴 지도에서 찾기')}</section>`;
  const menus=profile.menus||[],recommended=menus.filter(m=>m.recommended),preview=(recommended.length?recommended:menus).slice(0,3),remaining=menus.filter(m=>!preview.includes(m));
  const menuRows=items=>items.map(m=>`<li><div><span>${safe(m.name)}</span><small>메뉴 등록 ${safe(R.menuDate(m,profile)||'일자 미제공')}${R.staleMenu(m,profile)?' · 현 가격 확인 필요':''}</small></div><b>${m.price_krw>0?money(m.price_krw):safe(m.price_text||'가격 미등록')}</b></li>`).join('');
  return `<section class="restaurant-info"><h3>어떤 식당인가요?</h3><span class="restaurant-category">${safe(profile.category_path?.join(' › ')||profile.category||'업종 미등록')}</span>${profile.status!=='Y'?'<p class="profile-warning">영업 상태를 방문 전에 확인해 주세요.</p>':''}<p>${safe(profile.name)} · ${safe(profile.address)}</p><h3>대표메뉴 · 가격</h3>${recommended.length?'<p>출처에서 추천으로 표시한 메뉴입니다.</p>':'<p>출처에 대표·추천 메뉴 표시가 없습니다. 아래는 등록된 메뉴입니다.</p>'}<ul class="menu-list">${menuRows(preview)}</ul>${remaining.length?`<details class="registered-menus"><summary>등록 메뉴 ${remaining.length}개 더 보기</summary><ul class="menu-list">${menuRows(remaining)}</ul></details>`:''}${!menus.length?'<p>등록된 메뉴·가격이 없습니다.</p>':''}<p class="menu-note">등록 가격은 현재 가격이나 과거 결제 당시 가격과 다를 수 있습니다. 아래 지출에서 실제 주문한 메뉴를 뜻하지 않습니다.</p><div class="profile-source">${externalLink(profile.source_url,profile.source_name||'식당 정보 출처')}<small>정보 조회 ${safe(profile.checked_at?.slice(0,10)||'미확인')}</small></div></section>`;
}
function renderDetail(){
  if(!selectedDetail)return;
  const state=selectedDetail,group=state.groups[state.active],items=group.rows,s=C.stats(items),x=items[0];selected=items;
  const sorted=items.slice().sort((a,b)=>(b.date||'').localeCompare(a.date||''));
  const knownDates=sorted.map(r=>r.date).filter(Boolean),institutions=C.group(items,r=>r.institution).sort((a,b)=>b.total-a.total);
  $('detail').innerHTML=`<button class="close-detail" aria-label="상세 닫기">×</button><div class="eyebrow">${mode==='demo'?'SAMPLE DATA · 가상 자료':'RESTAURANT & PUBLIC SPENDING'}</div>${state.groups.length>1?`<p>같은 지도 위치의 사용처입니다. 식당을 선택해 주세요.</p><div class="venue-choices">${state.groups.map((g,i)=>`<button data-venue="${i}" class="${state.active===i?'active':''}" aria-pressed="${state.active===i}">${safe(g.name)}</button>`).join('')}</div>`:''}<h2>${safe(x.merchant)}</h2><div class="restaurant-type-tags">${typeBadges(x)}</div><p class="type-basis">분류 근거: ${safe(restaurantType(x).evidence)}</p><p>${safe((x.address||'사용처의 정확한 주소는 확인 대기 중입니다.')+(items.some(inferredAddress)?' · 원문에 주소가 없어 공개 지도에서 상호·지역을 대조한 주소입니다. 실제 결제 지점은 원문 확인이 필요합니다.':x.location?.precision==='address'?' · 지도는 주소·건물 기준 위치':''))}</p>${externalLink(x.location?.evidence_url,'지도 사업장·주소 확인')}${restaurantInfo(x)}<section class="spending-section"><h3>어디서 · 언제 · 얼마나 썼나요?</h3><p>현재 선택한 기간·기관 등 필터에 해당하는 이 사용처의 공개 내역입니다.</p><div class="detail-total">${money(s.total)}</div><div class="detail-grid"><div>공개 집행<b>${s.count}건</b></div><div>기재 연인원<b>${s.people}명</b></div><div>기재 기준 인당<b>${money(s.perPerson)}</b></div></div><p>${knownDates.length?'집행 기간 '+safe(knownDates[knownDates.length-1])+' ~ '+safe(knownDates[0]):'집행 날짜 미공개'}</p><details class="institution-summary"><summary>사용 기관 ${institutions.length}곳 · 기관별 합계</summary>${institutions.map(g=>`<div><span>${safe(g.key)} · ${g.count}건</span><b>${money(g.total)}</b></div>`).join('')}</details>${sorted.slice(0,state.limit).map(r=>`<article><strong>${safe(r.institution)} · ${safe(r.department)}</strong><dl class="expense-facts"><div><dt>언제</dt><dd>${safe(r.date)}</dd></div><div><dt>사용처</dt><dd>${safe(r.merchant)}</dd></div><div><dt>목적</dt><dd>${safe(r.purpose)}</dd></div><div><dt>인원</dt><dd>${safe(r.participant_text|| (r.participants>0?r.participants+'명':'미공개'))}</dd></div><div><dt>집행액</dt><dd><b>${money(r.amount_krw)}</b> · 인당 ${money(r.participants>0?r.amount_krw/r.participants:null)}</dd></div><div><dt>결제·항목</dt><dd>${safe(r.payment_method)} · ${safe(r.budget_category||r.category)}</dd></div></dl>${externalLink(r.source_post_url,'공개 게시글')}${externalLink(r.source_url,'공개 원문에서 확인')||'<span class="per-person">가상 자료 · 실제 지출이 아닙니다</span>'}</article>`).join('')}${sorted.length>state.limit?`<button class="more-expenses">내역 더 보기 (${Math.min(state.limit,sorted.length)} / ${sorted.length}건)</button>`:''}<p>인원은 공개자료 기재값이며 반복 참석을 포함합니다. 실제 참석 여부와 주문 메뉴는 확인되지 않았습니다.${!x.location?' 식당 지점·좌표 확인 후 지도에 표시합니다.':''}</p></section>`;
  $('detail').querySelector('.close-detail').onclick=()=>{$('detail').hidden=true;selectedDetail=null;};
  $('detail').querySelectorAll('[data-venue]').forEach(button=>button.onclick=()=>{state.active=Number(button.dataset.venue);state.limit=50;renderDetail();});
  const more=$('detail').querySelector('.more-expenses');if(more)more.onclick=()=>{const scroll=$('detail').scrollTop;state.limit+=100;renderDetail();$('detail').scrollTop=scroll;};
}
function show(items){
  const groups=MealRestaurants.selectVenues(items,rows());if(!groups.length)return;
  const state={groups,active:0,limit:50};selectedDetail=state;$('detail').hidden=false;$('detail').scrollTop=0;renderDetail();
  if(mode==='real')loadRestaurantProfiles().then(()=>{if(selectedDetail===state&&!$('detail').hidden){const scroll=$('detail').scrollTop;renderDetail();$('detail').scrollTop=scroll;}});
}

['search','period','institution','region','city','category','restaurant-type'].forEach(id=>$(id).addEventListener(id==='search'?'input':'change',()=>{selected=null;$('detail').hidden=true;if(id==='city'&&C.cities[$(id).value]){$('region').value='경기';if(map)focusRegion(rows(),C.cities[$(id).value]);}if(id==='region'&&$('region').value!=='경기')$('city').value='all';if(id==='region'&&map&&C.regions[$(id).value])focusRegion(rows(),C.regions[$(id).value]);render();}));
$('real').onclick=()=>setMode('real');$('demo').onclick=()=>setMode('demo');$('metric-total').onclick=()=>setMetric('total');$('metric-person').onclick=()=>setMetric('person');function setMetric(m){metric=m;$('metric-total').classList.toggle('active',m==='total');$('metric-person').classList.toggle('active',m==='person');scheduleDraw();}
$('reset-map').onclick=()=>{$('region').value='all';$('city').value='all';if(map)map.setView([36.1,127.8],7);render();};$('about').onclick=()=>$('info').showModal();$('close-info').onclick=()=>$('info').close();$('info').onclick=e=>{if(e.target===$('info'))$('info').close();};
$('export').onclick=()=>{const keys=['date','institution','department','merchant','address','address_match','spending_region','spending_city','purpose','amount_krw','participants','per_person_krw','restaurant_types','restaurant_type_basis','source_url'];const cell=v=>'"'+String(v??'').replace(/^[=+@\-]/,"'$&").replace(/"/g,'""')+'"';const csv='\ufeff'+[keys,...rows().map(r=>keys.map(k=>k==='restaurant_types'?restaurantType(r).tags.join(' / '):k==='restaurant_type_basis'?restaurantType(r).evidence:k==='per_person_krw'?(r.participants>0?Math.round(r.amount_krw/r.participants):null):r[k]))].map(a=>a.map(cell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=mode==='demo'?'가상자료-실제지출아님.csv':'공개업무추진비.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
if(typeof L!=='undefined'){map=L.map('map',{zoomControl:false,preferCanvas:true,renderer:L.canvas({tolerance:8}),minZoom:6,maxZoom:18}).setView([36.1,127.8],7);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>',maxZoom:19}).addTo(map);L.control.zoom({position:'bottomright'}).addTo(map);layer=L.layerGroup().addTo(map);map.on('zoomend moveend',scheduleDraw);}else{$('map-help').textContent='지도를 불러오지 못했습니다. 지출 목록은 계속 볼 수 있습니다.';}
$('restaurant-type').replaceChildren(new Option('전체 식당 종류','all'),...MealRestaurants.restaurantTypes.map(t=>new Option(t,t)));
fetch('data.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('자료를 불러오지 못했습니다');return r.json();}).then(async data=>{if(data.full_data){if(typeof DecompressionStream==='undefined'){data.scope='이 브라우저는 압축 이력을 지원하지 않아 최신 '+data.records.length+'건만 표시합니다.';}else{const response=await fetch(data.full_data,{cache:'no-store'});if(!response.ok)throw Error('이력 로딩 실패');const bytes=new Uint8Array(await response.arrayBuffer());const text=bytes[0]===31&&bytes[1]===139?await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).text():new TextDecoder().decode(bytes);data=C.unpackSnapshot(JSON.parse(text));}}await loadRestaurantProfiles();allRows=data.records;filteredKey=null;allScope=data.scope||'수집 범위 확인 중';$('updated').textContent='수집 '+new Date(data.updated_at).toLocaleString('ko-KR',{timeZone:'Asia/Seoul',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit',hour12:false});setMode('real');const requestedRegion=new URLSearchParams(location.search).get('region');if(requestedRegion&&C.regions[requestedRegion]){$('region').value=requestedRegion;if(map)focusRegion(rows(),C.regions[requestedRegion]);render();}const requestedCity=new URLSearchParams(location.search).get('city')?.replace(/(?:특례)?시$/,'');if(requestedCity&&C.cities[requestedCity]){$('region').value='경기';$('city').value=requestedCity;if(map)focusRegion(rows(),C.cities[requestedCity]);render();}const requestedInstitution=new URLSearchParams(location.search).get('institution');if(requestedInstitution)chooseInstitution(requestedInstitution);const failed=(data.source_status||[]).filter(s=>s.status==='failed');const partial=(data.source_status||[]).filter(s=>s.status==='partial');if(partial.length)$('mode-note').textContent+=' 일부 첨부 형식은 미지원으로 부분 수집: 데이터 안내 참조.';if(failed.length)$('mode-note').textContent+=' 일부 출처 '+failed.length+'건 갱신 실패: 기존 자료 유지.';}).catch(()=>{$('mode-note').textContent='실자료 파일을 불러오지 못했습니다. 새로고침하거나 화면 체험을 이용하세요.';$('updated').textContent='데이터 로딩 실패';});
